#!/usr/bin/env python3
"""TEST ONLY source-guarded V1.3 installer. Actual readable source emitted by CI."""
import base64,zlib,hashlib
payload=""
source=zlib.decompress(base64.b64decode(payload))
assert hashlib.sha256(source).hexdigest()=="b3b9b21ca3afc1faf6c811109b8a5451b60f59b8390ba3ad5a082e53fff3a955"
# Safety hardening: diagnostics must NEVER be archived into wolfconfig.
old=b'ri.Cvar_Get("r_dwFireWorldMaskProbe", "0", CVAR_ARCHIVE);'
new=b'ri.Cvar_Get("r_dwFireWorldMaskProbe", "0", CVAR_TEMP);'
assert source.count(old)==1
source=source.replace(old,new)
assert hashlib.sha256(source).hexdigest()=="6ca756dea0b6cf33eebd6b109565a7a5ca0d249527ec67ec10bc90acf9adb4d5"
exec(compile(source.decode("utf-8"),"dw_fire_world_v13.py","exec"))
